133	+export type IdleState = 'ok' | 'warn' | 'expired';
134	+
135	+export class ExIdle {
136	+  private last = 0;   // ms — mốc phím cuối (hoặc mốc reset)
137	+  constructor(private idleMs: number, private warnMs: number) {}
138	+
139	+  activity(now: number): void { this.last = now; }
140	+  reset(now: number): void { this.last = now; }
141	+
142	+  tick(now: number): IdleState {
143	+    const d = now - this.last;
144	+    return d < this.idleMs ? 'ok' : d < this.idleMs + this.warnMs ? 'warn' : 'expired';
145	+  }
146	+
147	+  /* Số giây còn lại tới lúc hết hạn, làm tròn lên (không âm) */
148	+  remaining(now: number): number {
149	+    return Math.max(0, Math.ceil((this.idleMs + this.warnMs - (now - this.last)) / 1000));
150	+  }
151	+}
